<script setup lang="ts">import {computed} from 'vue';import {Plus,ArrowUpRight} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import RunSummary from '../components/RunSummary.vue';import SpectralPlot from '../components/SpectralPlot.vue';import Notice from '../components/common/Notice.vue';const s=useResearchData(),auth=useAuth(),run=computed(()=>s.runs.find(r=>r.status==='completed'));</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">MATERIAL DESK / 01</p><h1>样本总览<span>先辨识端元，再解释混合样本。</span></h1></div><RouterLink v-if="auth.user?.role!=='viewer'" class="outline" to="/configure"><Plus :size="16"/>建立解混研究</RouterLink></div><Notice :message="s.error" @retry="s.refresh"/><div class="overview-grid"><section class="evidence-sheet"><div class="section-top"><span class="eyebrow">LATEST SPECTRAL EVIDENCE</span><RouterLink to="/results">展开配比 <ArrowUpRight :size="14"/></RouterLink></div><template v-if="run"><RunSummary :run="run"/><SpectralPlot :library="run.result.library" :endmembers="run.result.endmembers" :sample="run.result.samples[0]"/></template><p v-else class="empty">尚无解混研究，请先核对光谱库并选择混合样本。</p></section><aside class="material-note"><span class="eyebrow">READING NOTE / 001</span><h2>残差，<br/>不只有噪声。</h2><p>端元校准、线性混合与测量条件都可能造成偏离。固定sigma的扰动范围，不能包办这些不确定性。</p><div class="note-divider"/><b>{{s.libraries.reduce((n,l)=>n+l.sample_count,0)}}</b><span>混合样本 / {{s.libraries.length}} 份光谱库</span><RouterLink to="/inputs">核对端元与边界例 →</RouterLink></aside></div><div class="section-heading"><h2>光谱库册页</h2><span>12波段 / 400–675 nm</span></div><div class="library-list"><RouterLink v-for="l in s.libraries" :key="l.id" :to="'/inputs?library='+l.id"><span class="eyebrow">{{l.code}}</span><div><h3>{{l.name}}</h3><p>{{l.endmember_count}} 端元 / {{l.sample_count}} 样本</p></div><b :class="l.supported?'supported':'warning'">{{l.supported?'可解混':'病态边界 / 拒绝解释'}}</b></RouterLink></div></div></template>
